<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Withdrawals | AppTasker</title><style>body{margin:0;background:#f5f7fb;font-family:Inter,system-ui;color:#182230}.w{max-width:1100px;margin:auto;padding:24px 16px}.back{color:#526df5;text-decoration:none;font-weight:800}.card{background:#fff;border:1px solid #e7eaf0;border-radius:18px;padding:18px;margin:13px 0}.row{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px}.muted{color:#667085;font-size:12px}.form{display:flex;gap:8px;margin-top:14px}.in{padding:10px;border:1px solid #d7dce5;border-radius:9px}.btn{border:0;background:#526df5;color:#fff;padding:10px 13px;border-radius:9px;font-weight:800}.msg{background:#ecfdf3;padding:12px;border-radius:10px}@media(max-width:650px){.row{grid-template-columns:1fr}.form{display:grid}}</style></head><body><main class="w"><a class="back" href="{{ route('admin.dashboard') }}">← Dashboard</a><h1>Withdrawal Requests</h1>@if(session('success'))<p class="msg">{{ session('success') }}</p>@endif @forelse($withdrawals as $w)<section class="card"><div class="row"><div><strong>{{ $w->user->name }}</strong><div class="muted">{{ $w->user->email }} · {{ $w->method }} · {{ $w->account }}</div></div><strong>${{ number_format((float)$w->amount,2) }}</strong><strong>{{ ucfirst($w->status) }}</strong></div><form class="form" method="POST" action="{{ route('admin.withdrawals.update',$w) }}">@csrf @method('PATCH')<input class="in" name="admin_note" placeholder="Admin note"><select class="in" name="status"><option value="approved">Approve</option><option value="rejected">Reject</option><option value="paid">Mark Paid</option></select><button class="btn">Update</button></form></section>@empty<p>No withdrawal requests.</p>@endforelse{{ $withdrawals->links() }}</main></body></html>